(6303000, 931994, 30364, '<td valign="top">Clever.  Such an unexpected idea in this challenge, and so well executed.  Thank you.</td>', 'Clever.  Such an unexpected idea in this challenge, and so well executed.  Thank you.', '2011-02-04 16:37:52.000000', NULL, 1),
(6303002, 932811, 30364, '<td valign="top">Wonderfully incomprehensible.  Thank you.</td>', 'Wonderfully incomprehensible.  Thank you.', '2011-02-04 16:41:00.000000', NULL, 1),
(6303004, 932260, 30364, '<td valign="top">Beautiful.  Thank you.</td>', 'Beautiful.  Thank you.', '2011-02-04 16:45:37.000000', NULL, 1),
(6303011, 932577, 30364, '<td valign="top">Lovely use of space, tone and point-of-view.  You''ve achieved remarkable poise for such a potentially difficult idea.  Thank you.</td>', 'Lovely use of space, tone and point-of-view.  You''ve achieved remarkable poise for such a potentially difficult idea.  Thank you.', '2011-02-04 16:50:32.000000', NULL, 1),
(6303017, 932542, 30364, '<td valign="top">Witty, little bit sly, but very beautiful as well.  Thank you, for all three.</td>', 'Witty, little bit sly, but very beautiful as well.  Thank you, for all three.', '2011-02-04 16:54:13.000000', NULL, 1),
(6303018, 931890, 30364, '<td valign="top">A ''grainstorm'' and worth getting wet for!  Thank you.</td>', 'A ''grainstorm'' and worth getting wet for!  Thank you.', '2011-02-04 16:54:26.000000', NULL, 1),
(6303020, 932853, 30364, '<td valign="top">Absurdly wonderful in every way.  Qui vive indeed.  Thank you.</td>', 'Absurdly wonderful in every way.  Qui vive indeed.  Thank you.', '2011-02-04 16:59:05.000000', NULL, 1),
(6303022, 932829, 30364, '<td valign="top">Too damn clever!  A beautiful, perplexing tease.  Thank you.</td>', 'Too damn clever!  A beautiful, perplexing tease.  Thank you.', '2011-02-04 17:02:19.000000', NULL, 1),
(6303027, 932230, 30364, '<td valign="top">Suitably anarchic.  Lovely nonetheless.  Thank you.</td>', 'Suitably anarchic.  Lovely nonetheless.  Thank you.', '2011-02-04 17:04:31.000000', NULL, 1),
(6303196, 932230, 64086, '<td valign="top">Wonderful canvas of light and texture. It draws me in.</td>', 'Wonderful canvas of light and texture. It draws me in.', '2011-02-04 21:51:45.000000', NULL, 1),
(6303267, 932842, 76335, '<td valign="top">Nice the way it punctures the landscape.</td>', 'Nice the way it punctures the landscape.', '2011-02-05 00:18:19.000000', NULL, 1),
(6303268, 932137, 76335, '<td valign="top">Perfect!</td>', 'Perfect!', '2011-02-05 00:19:43.000000', NULL, 1),
(6303269, 932853, 76335, '<td valign="top">Now this is unique. Amazing how a little highlight clipping can transform a scene into something fantastic.</td>', 'Now this is unique. Amazing how a little highlight clipping can transform a scene into something fantastic.', '2011-02-05 00:21:13.000000', NULL, 1),
(6303270, 932805, 76335, '<td valign="top">Oh wise one...</td>', 'Oh wise one...', '2011-02-05 00:21:25.000000', NULL, 1),
(6303271, 932670, 76335, '<td valign="top">Beautiful tones in this. A very effective composition too.</td>', 'Beautiful tones in this. A very effective composition too.', '2011-02-05 00:22:01.000000', NULL, 1),
(6303273, 932434, 76335, '<td valign="top">A vestige of yesterday''s technology. Love the grit.</td>', 'A vestige of yesterday''s technology. Love the grit.', '2011-02-05 00:23:07.000000', NULL, 1),
(6303275, 932554, 76335, '<td valign="top">Most effective point of view.</td>', 'Most effective point of view.', '2011-02-05 00:24:47.000000', NULL, 1),
(6303276, 932338, 76335, '<td valign="top">Fulibeaut.</td>', 'Fulibeaut.', '2011-02-05 00:25:34.000000', NULL, 1),
(6303278, 932041, 76335, '<td valign="top">Wonderful framing. Does he live there?</td>', 'Wonderful framing. Does he live there?', '2011-02-05 00:26:13.000000', NULL, 1),
(6303314, 932140, 113228, '<td valign="top">MY TOWN</td>', 'MY TOWN', '2011-02-05 04:15:43.000000', NULL, 1),
(6303398, 932137, 63218, '<td valign="top">This is ridiculous! and adorable! Well seen.</td>', 'This is ridiculous! and adorable! Well seen.', '2011-02-05 10:07:17.000000', NULL, 1),
(6303446, 932829, 76335, '<td valign="top">An intriguing composition that suggests more than it depicts.</td>', 'An intriguing composition that suggests more than it depicts.', '2011-02-05 11:19:43.000000', NULL, 1),
(6303447, 932048, 76335, '<td valign="top">Nicely composed, interesting lighting. I would expect the light to make the nose appear unflattering. But she has a nice nose.</td>', 'Nicely composed, interesting lighting. I would expect the light to make the nose appear unflattering. But she has a nice nose.', '2011-02-05 11:21:00.000000', NULL, 1),
(6303450, 932788, 76335, '<td valign="top">Yeah! Love this. The low point of view elevates the scrawny, tiny creature to a more imposing status. The tree and light-to-dark balance the composition beautifully.</td>', 'Yeah! Love this. The low point of view elevates the scrawny, tiny creature to a more imposing status. The tree and light-to-dark balance the composition beautifully.', '2011-02-05 11:22:19.000000', NULL, 1),
(6303456, 932764, 76335, '<td valign="top">Nice the way the tree expands to fill the frame. The bench is nicely framed with the surrounding elements.</td>', 'Nice the way the tree expands to fill the frame. The bench is nicely framed with the surrounding elements.', '2011-02-05 11:23:40.000000', NULL, 1),
(6303462, 931994, 76335, '<td valign="top">This is interesting. Nicely composed, great tones, and it has a certain energy to it.</td>', 'This is interesting. Nicely composed, great tones, and it has a certain energy to it.', '2011-02-05 11:25:23.000000', NULL, 1),
(6303465, 932456, 76335, '<td valign="top">I do appreciate the simplicity of your composition. Normally I complain about titlted horizons, but here it seems to work.</td>', 'I do appreciate the simplicity of your composition. Normally I complain about titlted horizons, but here it seems to work.', '2011-02-05 11:26:17.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6303471, 932698, 76335, '<td valign="top">What bizarre geological matter up front. The sky look unreal too. Interesting way to frame your lighthouse.</td>', 'What bizarre geological matter up front. The sky look unreal too. Interesting way to frame your lighthouse.', '2011-02-05 11:27:40.000000', NULL, 1),
(6303476, 932831, 76335, '<td valign="top">Great idea, interesting processing.</td>', 'Great idea, interesting processing.', '2011-02-05 11:28:57.000000', NULL, 1),
(6303479, 932577, 76335, '<td valign="top">I do like that the contrast doesn''t pop. The quick-fingered voter will miss all the magic of this image.</td>', 'I do like that the contrast doesn''t pop. The quick-fingered voter will miss all the magic of this image.', '2011-02-05 11:31:06.000000', NULL, 1),
(6303482, 932604, 76335, '<td valign="top">The slight motion blur and low point of view makes them look almost vicious.</td>', 'The slight motion blur and low point of view makes them look almost vicious.', '2011-02-05 11:32:12.000000', NULL, 1),
(6303486, 932230, 63218, '<td valign="top">I almost think I can almost see a saggy old abandoned house back there in the shadows.</td>', 'I almost think I can almost see a saggy old abandoned house back there in the shadows.', '2011-02-05 11:33:08.000000', NULL, 1),
(6303488, 932770, 76335, '<td valign="top">Interesting with the shoes. Catching him mid-stride was a good idea.</td>', 'Interesting with the shoes. Catching him mid-stride was a good idea.', '2011-02-05 11:33:22.000000', NULL, 1),
(6303490, 932260, 76335, '<td valign="top">Lyrical.</td>', 'Lyrical.', '2011-02-05 11:33:35.000000', NULL, 1),
(6303492, 932836, 76335, '<td valign="top">Smart framing. Telephoto was a good idea for this.</td>', 'Smart framing. Telephoto was a good idea for this.', '2011-02-05 11:34:27.000000', NULL, 1),
(6303493, 932329, 63218, '<td valign="top">The sunburnt view thru the window frame complements the broken down old chair very nicely. Some very nice light in this.</td>', 'The sunburnt view thru the window frame complements the broken down old chair very nicely. Some very nice light in this.', '2011-02-05 11:34:31.000000', NULL, 1),
(6303495, 932542, 76335, '<td valign="top">Pure poetry.</td>', 'Pure poetry.', '2011-02-05 11:35:08.000000', NULL, 1),
(6303496, 932467, 76335, '<td valign="top">Grainy textures everywhere. Beautiful.</td>', 'Grainy textures everywhere. Beautiful.', '2011-02-05 11:36:15.000000', NULL, 1),
(6303497, 932853, 63218, '<td valign="top">That''s one compelling face. The shoes seem to be from another time. Well done.</td>', 'That''s one compelling face. The shoes seem to be from another time. Well done.', '2011-02-05 11:36:40.000000', NULL, 1),
(6303501, 931890, 76335, '<td valign="top">Beautifully monolithic. Nothing in the frame to take away from the singularity of your form. For that matter, quite possibly the most "sentinel" thing in this challenge.</td>', 'Beautifully monolithic. Nothing in the frame to take away from the singularity of your form. For that matter, quite possibly the most "sentinel" thing in this challenge.', '2011-02-05 11:39:00.000000', NULL, 1),
(6303504, 932224, 76335, '<td valign="top">I love the way it punctures the horizon.</td>', 'I love the way it punctures the horizon.', '2011-02-05 11:39:42.000000', NULL, 1),
(6303506, 932639, 76335, '<td valign="top">Most sinister against that foreboding yellow backdrop.</td>', 'Most sinister against that foreboding yellow backdrop.', '2011-02-05 11:40:09.000000', NULL, 1),
(6303509, 932811, 76335, '<td valign="top">Ironic title. Sinister. The stuff nightmares are made of.</td>', 'Ironic title. Sinister. The stuff nightmares are made of.', '2011-02-05 11:41:59.000000', NULL, 1),
(6303514, 932230, 76335, '<td valign="top">Like a charcoal drawing. Simply beautiful.</td>', 'Like a charcoal drawing. Simply beautiful.', '2011-02-05 11:43:34.000000', NULL, 1),
(6303516, 931754, 76335, '<td valign="top">A great scene marred by heavyhanded processing.</td>', 'A great scene marred by heavyhanded processing.', '2011-02-05 11:44:05.000000', NULL, 1),
(6303519, 932603, 76335, '<td valign="top">An interesting scene that perhaps needs a little something else to give it imapact.</td>', 'An interesting scene that perhaps needs a little something else to give it imapact.', '2011-02-05 11:44:56.000000', NULL, 1),
(6303523, 932066, 76335, '<td valign="top">One of the better lone tree shots in this challenge. It''s perfectly placed in the frame and the streaks of clouds add good counterpoint.</td>', 'One of the better lone tree shots in this challenge. It''s perfectly placed in the frame and the streaks of clouds add good counterpoint.', '2011-02-05 11:46:19.000000', NULL, 1),
